import { useState } from "react";
import axios from "axios";
import { QRCodeSVG } from "qrcode.react";
import "./App.css";

export default function Register({ onBack, onRegisterSuccess }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [qr, setQr] = useState("");
  const [error, setError] = useState("");
  const [redirectTimer, setRedirectTimer] = useState(null);

  const validateForm = () => {
    if (!email || !password || !confirmPassword) {
      setError("Te rog completează toate câmpurile!");
      return false;
    }
    if (password.length < 8) {
      setError("Parola trebuie să aibă minim 8 caractere!");
      return false;
    }
    if (password !== confirmPassword) {
      setError("Parolele nu se potrivesc!");
      return false;
    }
    if (!/\S+@\S+\.\S+/.test(email)) {
      setError("Adresa de email nu este validă!");
      return false;
    }
    setError("");
    return true;
  };

  const handleRegister = async () => {
    if (!validateForm()) return;

    try {
      const res = await axios.post("http://localhost:8001/register", { email, password });
      if (res.data.otp_uri) {
        setQr(res.data.otp_uri);
        setError("");
        // Auto-redirect to login after 3 seconds
        setTimeout(() => {
          onRegisterSuccess();
        }, 3000);
      }
      if (res.data.error) {
        setError(res.data.error);
      }
    } catch (err) {
      setError("Eroare la înregistrare. Verifică conexiunea!");
    }
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh", paddingTop: "2rem", paddingBottom: "2rem" }}>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo">
            🍳 SmartChef
          </div>
        </div>
      </header>

      <div className="form-container">
        <div style={{ textAlign: "center", marginBottom: "2rem" }}>
          <h2 style={{ fontSize: "2.2rem", fontWeight: "700", color: "#ff6b35", marginBottom: "0.5rem" }}>
            Înregistrare
          </h2>
          <p style={{ color: "#666", fontSize: "1rem" }}>
            Creează un cont nou SmartChef
          </p>
        </div>

        {error && (
          <div style={{
            background: "#fee",
            border: "2px solid #fcc",
            borderRadius: "12px",
            padding: "1rem",
            marginBottom: "1.5rem",
            color: "#c33",
            fontWeight: "500"
          }}>
            ⚠️ {error}
          </div>
        )}

        <div className="form-group">
          <label className="form-label">Email</label>
          <input
            className="form-input"
            type="email"
            placeholder="exemplu@email.com"
            value={email}
            onChange={e => setEmail(e.target.value)}
          />
        </div>

        <div className="form-group">
          <label className="form-label">Parolă</label>
          <input
            className="form-input"
            type="password"
            placeholder="Minim 8 caractere"
            value={password}
            onChange={e => setPassword(e.target.value)}
          />
          <p style={{ fontSize: "0.85rem", color: "#999", marginTop: "0.3rem" }}>
            Minim 8 caractere, o literă mare, o cifră
          </p>
        </div>

        <div className="form-group">
          <label className="form-label">Confirmă Parola</label>
          <input
            className="form-input"
            type="password"
            placeholder="Rescrie parola"
            value={confirmPassword}
            onChange={e => setConfirmPassword(e.target.value)}
          />
        </div>

        <button
          className="btn btn-primary"
          onClick={handleRegister}
          style={{ width: "100%", padding: "1rem", fontSize: "1.1rem", marginTop: "1rem" }}
        >
          📝 Înregistrează-te
        </button>

        <button
          className="btn btn-secondary"
          onClick={onBack}
          style={{ width: "100%", padding: "1rem", fontSize: "1.1rem", marginTop: "1rem" }}
        >
          ← Înapoi
        </button>

        {qr && (
          <div style={{
            marginTop: "2rem",
            padding: "2rem",
            background: "linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%)",
            borderRadius: "20px",
            border: "3px solid #4CAF50"
          }}>
            <h3 style={{ textAlign: "center", color: "#2e7d32", marginBottom: "1rem", fontSize: "1.3rem" }}>
              ✅ Cont creat cu succes!
            </h3>
            <p style={{ textAlign: "center", marginBottom: "1.5rem", color: "#666" }}>
              Scanează codul QR cu Google Authenticator:
            </p>
            <div style={{ display: "flex", justifyContent: "center", background: "white", padding: "1.5rem", borderRadius: "15px" }}>
              <QRCodeSVG value={qr} size={220} />
            </div>
            <p style={{ textAlign: "center", marginTop: "1.5rem", fontSize: "0.9rem", color: "#666" }}>
              💡 Vei avea nevoie de codul din aplicație pentru login
            </p>
            <p style={{ textAlign: "center", marginTop: "1rem", fontSize: "0.95rem", color: "#2e7d32", fontWeight: "600" }}>
              ⏳ Vei fi redirecționat la Login în 3 secunde...
            </p>
            <button
              className="btn btn-primary"
              onClick={onRegisterSuccess}
              style={{ width: "100%", padding: "1rem", fontSize: "1.1rem", marginTop: "1.5rem" }}
            >
              ✅ Continuă la Login Acum
            </button>
          </div>
        )}

        <p style={{ textAlign: "center", marginTop: "2rem", color: "#666" }}>
          Ai deja cont?{" "}
          <span
            onClick={onBack}
            style={{ color: "#ff6b35", fontWeight: "600", cursor: "pointer", textDecoration: "underline" }}
          >
            Login aici
          </span>
        </p>
      </div>
    </div>
  );
}
